-- ----------------------------
-- Table structure for embedding_model_info
-- ----------------------------
DROP TABLE IF EXISTS `embedding_model_info`;
CREATE TABLE `embedding_model_info`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `model` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '向量模型名称，如 text-embedding-3-large、bge-m3',
  `model_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台内部模型编码，用于业务侧唯一识别',
  `manufacturer_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型厂商编码，对应 model_manufacturer.manufacturer_code',
  `base_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型服务Base URL',
  `api_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型服务API Key，建议生产环境加密存储',
  `dimension` int NOT NULL COMMENT '向量维度，如 768、1024、1536、3072',
  `max_input_tokens` int NULL DEFAULT NULL COMMENT '单次最大输入Token数',
  `batch_size` int NULL DEFAULT NULL COMMENT '单次批量Embedding最大条数',
  `distance_metric` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'COSINE' COMMENT '推荐距离度量：COSINE、L2、IP',
  `normalize` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否对向量归一化：0-否，1-是',
  `model_describe` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型描述',
  `config` json NULL COMMENT '扩展配置，如超时、重试、请求头、供应商特殊参数',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：0-停用，1-启用',
  `version` bigint NOT NULL DEFAULT 0 COMMENT '版本号，用于乐观锁或配置变更追踪',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_embedding_model_model_code`(`model_code` ASC) USING BTREE,
  INDEX `idx_embedding_model_manufacturer_code`(`manufacturer_code` ASC) USING BTREE,
  INDEX `idx_embedding_model_status`(`status` ASC) USING BTREE,
  INDEX `idx_embedding_model_dimension`(`dimension` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '平台级别-向量模型信息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of embedding_model_info
-- ----------------------------
INSERT INTO `embedding_model_info` VALUES (1, 'text-embedding-v4', 'text-embedding-v4', 'QWEN', 'https://dashscope.aliyuncs.com/compatible-mode', 'sk-3398a71a31f04728a19922dcbb8af1f9', 1024, 8192, 10, 'COSINE', 0, '是通义实验室基于Qwen3训练的多语言文本统一向量模型，相较V3版本在文本检索、聚类、分类性能大幅提升；在MTEB多语言、中英、Code检索等评测任务上效果提升15%~40%；支持64~2048维用户自定义向量维度。', NULL, 1, 0, '2026-06-09 08:53:08', '2026-06-09 09:16:22', 0);

-- ----------------------------
-- Table structure for eval_pipeline_node_detail
-- ----------------------------
DROP TABLE IF EXISTS `eval_pipeline_node_detail`;
CREATE TABLE `eval_pipeline_node_detail`  (
  `id` bigint NOT NULL COMMENT '主键ID',
  `task_id` bigint NOT NULL COMMENT '评测任务ID，对应 eval_task.id',
  `task_detail_id` bigint NOT NULL COMMENT '任务执行批次ID，对应 eval_task_detail.id',
  `result_detail_id` bigint NOT NULL COMMENT '评测结果明细ID，对应 eval_result_detail.id',
  `sample_id` bigint NULL DEFAULT NULL COMMENT '数据集样本ID，对应 dataset_sample.id',
  `node_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点编码：MODEL_CALL-模型调用，L1-L1字面量拦截，L2-L2召回，L3-L3裁决',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点状态：RUNNING-执行中，PASSED-通过，BLOCKED-拦截，FAILED-失败，SKIPPED-跳过，STOPPED-终止',
  `start_time` datetime NULL DEFAULT NULL COMMENT '节点开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '节点结束时间',
  `latency` int NULL DEFAULT NULL COMMENT '节点耗时，单位毫秒',
  `error_msg` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '节点错误信息或短路原因',
  `input_snapshot` json NULL COMMENT '节点输入快照，保存必要上下文',
  `output_snapshot` json NULL COMMENT '节点输出快照，保存模型输出、召回结果或裁决结果摘要',
  `node_result` json NULL COMMENT '节点结构化结果，例如 L1 命中的 riskDetailsId、keyword、warningTags、decision',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_eval_pipeline_node_task_detail_id`(`task_detail_id` ASC) USING BTREE,
  INDEX `idx_eval_pipeline_node_result_detail_id`(`result_detail_id` ASC) USING BTREE,
  INDEX `idx_eval_pipeline_node_result_node`(`result_detail_id` ASC, `node_code` ASC) USING BTREE,
  INDEX `idx_eval_pipeline_node_task_node_status`(`task_detail_id` ASC, `node_code` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '评测流水线节点执行明细表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of eval_pipeline_node_detail
-- ----------------------------

