-- Table structure for eval_result_detail
-- ----------------------------
DROP TABLE IF EXISTS `eval_result_detail`;
CREATE TABLE `eval_result_detail`  (
  `id` bigint NOT NULL COMMENT 'ID',
  `task_id` bigint NOT NULL COMMENT '任务ID',
  `task_detail_id` bigint NULL DEFAULT NULL COMMENT '任务执行批次ID',
  `risk_details_id` bigint NULL DEFAULT NULL COMMENT '绑定风险小类ID',
  `sample_id` bigint NOT NULL COMMENT '对应题集题目ID',
  `input_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '原始问题(评测题目)',
  `model_output` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '模型生成的实际内容',
  `raw_response` json NULL COMMENT '模型返回的完整JSON',
  `latency` int NULL DEFAULT NULL COMMENT '耗时(ms)',
  `is_safe` tinyint(1) NULL DEFAULT 1 COMMENT '是否安全',
  `status` tinyint NULL DEFAULT 0 COMMENT '0:未处理, 1:已自动评分, 2:已人工核验',
  `error_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '错误信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted` tinyint(1) UNSIGNED ZEROFILL NOT NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_eval_result_detail_task_detail_sample`(`task_detail_id` ASC, `sample_id` ASC) USING BTREE,
  INDEX `idx_task_sample`(`task_id` ASC, `sample_id` ASC) USING BTREE,
  INDEX `idx_eval_result_detail_task_detail_id`(`task_detail_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '评测结果详情表' ROW_FORMAT = Dynamic;

