-- ----------------------------
-- Table structure for model_info
-- ----------------------------
DROP TABLE IF EXISTS `model_info`;
CREATE TABLE `model_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `model` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `base_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型url',
  `api_key` varbinary(255) NULL DEFAULT NULL COMMENT '应用密钥',
  `model_describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型描述',
  `manufacturer_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型厂商标识',
  `max_thread_size` bigint NULL DEFAULT 5 COMMENT '最大并发数',
  `max_completion_tokens` bigint NULL DEFAULT 500 COMMENT '生成词元数量',
  `stream` bit(1) NULL DEFAULT b'0' COMMENT '流式响应 默认0，非流式',
  `status` tinyint(1) NULL DEFAULT 1 COMMENT '状态 0 停用 1启用',
  `config` json NULL COMMENT '扩展配置',
  `version` bigint NOT NULL DEFAULT 1 COMMENT '版本号',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '是否删除0未删除1删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户模型表' ROW_FORMAT = DYNAMIC;

