-- ----------------------------
-- Table structure for knowledge_attack_feature
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_attack_feature`;
CREATE TABLE `knowledge_attack_feature`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID，作为 feature_id 使用',
  `risk_details_id` bigint NOT NULL COMMENT '关联 risk_details.id，风险小类ID',
  `risk_details_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '冗余风险小类名称',
  `category_id` bigint NULL DEFAULT NULL COMMENT '冗余风险大类ID，便于检索过滤和统计',
  `feature_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '特征业务编码，可选',
  `feature_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '攻击特征原文、payload、话术或安全例外样本',
  `normalized_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '归一化文本，用于 ES 检索和 hash 计算',
  `feature_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'KEYWORD' COMMENT '特征类型：KEYWORD、PAYLOAD、PROMPT_PATTERN、RESPONSE_PATTERN、JAILBREAK、SIMILAR_CASE、SAFE_EXCEPTION',
  `polarity` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'UNSAFE' COMMENT '极性：UNSAFE-风险特征，SAFE_EXCEPTION-安全例外',
  `risk_level` tinyint NOT NULL DEFAULT 2 COMMENT '风险等级：1-低，2-中，3-高，4-致命',
  `language` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'zh-CN' COMMENT '语言：zh-CN、en-US、mixed 等',
  `tags` json NULL COMMENT '标签，例如 jailbreak、payload、fraud、weapon、self-harm',
  `source` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '来源：manual、dataset、redteam、incident、generated',
  `weight` decimal(6, 3) NOT NULL DEFAULT 1.000 COMMENT '特征权重，用于召回融合和阈值调整',
  `content_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'feature_text 归一化后的 SHA-256，用于幂等去重',
  `version` int NOT NULL DEFAULT 1 COMMENT '特征版本，每次内容变更递增',
  `sync_status` tinyint NOT NULL DEFAULT 0 COMMENT '综合同步状态：0-待同步，1-已同步，2-同步失败，3-已删除待同步',
  `es_sync_status` tinyint NOT NULL DEFAULT 0 COMMENT 'ES同步状态：0-待同步，1-已同步，2-同步失败',
  `milvus_sync_status` tinyint NOT NULL DEFAULT 0 COMMENT 'Milvus同步状态：0-待同步，1-已同步，2-同步失败',
  `pg_sync_status` tinyint NOT NULL DEFAULT 0 COMMENT 'Milvus同步状态：0-待同步，1-已同步，2-同步失败',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '业务状态：0-禁用，1-启用',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除：0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_knowledge_attack_feature_hash`(`content_hash` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_knowledge_attack_feature_details`(`risk_details_id` ASC) USING BTREE,
  INDEX `idx_knowledge_attack_feature_category`(`category_id` ASC) USING BTREE,
  INDEX `idx_knowledge_attack_feature_sync`(`sync_status` ASC, `es_sync_status` ASC, `milvus_sync_status` ASC) USING BTREE,
  INDEX `idx_knowledge_attack_feature_status`(`status` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '大模型安全评测-攻击语义知识库表' ROW_FORMAT = Dynamic;

